/**
 * Re-export the real generated standup client under the name the build
 * wired into useStandup.ts. The canonical implementation lives in
 * app/src/api/standup/StandupClient.ts (generated by abi-codegen from the
 * compiled Rust ABI); this shim lets the generated/ import path work without
 * duplicating the implementation.
 */
export { StandupClient as AsyncstandupClient } from '../api/standup/StandupClient';
export type {
  StandupEntry,
  Comment,
  StandupBoard,
  AbiEvent,
  Event_CommentAdded,
  Event_StandupDeleted,
  Event_StandupEdited,
  Event_StandupPosted,
} from '../api/standup/StandupClient';
